import { MakeLogicType, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { teamLogic } from 'scenes/teamLogic'

import * as api from 'products/product_analytics/frontend/generated/api'
import type { EventsTableApi } from 'products/product_analytics/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface eventsTableSettingLogicValues {
    currentTeamId: number | null // teamLogic
    eventsTable: EventsTableApi | null
    eventsTableLoadFailed: boolean
    eventsTableLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface eventsTableSettingLogicActions {
    loadEventsTable: () => any
    loadEventsTableFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadEventsTableSuccess: (
        eventsTable: EventsTableApi | null,
        payload?: any
    ) => {
        eventsTable: EventsTableApi | null
        payload?: any
    }
    updateEventsTable: (useNewEventsTable: boolean) => boolean
    updateEventsTableFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    updateEventsTableSuccess: (
        eventsTable: EventsTableApi | null,
        payload?: boolean
    ) => {
        eventsTable: EventsTableApi | null
        payload?: boolean
    }
}

export type eventsTableSettingLogicType = MakeLogicType<eventsTableSettingLogicValues, eventsTableSettingLogicActions>

export const eventsTableSettingLogic = kea<eventsTableSettingLogicType>([
    path(['products', 'product_analytics', 'frontend', 'settings', 'eventsTableSettingLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        eventsTable: [
            null as EventsTableApi | null,
            {
                loadEventsTable: async () => {
                    if (values.currentTeamId === null) {
                        return null
                    }
                    return await api.eventsTableRetrieve(String(values.currentTeamId))
                },
                updateEventsTable: async (useNewEventsTable: boolean) => {
                    if (values.currentTeamId === null) {
                        return values.eventsTable
                    }
                    return await api.eventsTableUpdate(String(values.currentTeamId), {
                        use_new_events_table: useNewEventsTable,
                    })
                },
            },
        ],
    })),
    reducers({
        eventsTableLoadFailed: [
            false,
            {
                loadEventsTable: () => false,
                loadEventsTableFailure: () => true,
            },
        ],
    }),
    listeners(() => ({
        updateEventsTableSuccess: ({ eventsTable }) => {
            lemonToast.success(
                eventsTable?.use_new_events_table
                    ? 'This project now reads the new events table. It can take a minute to apply.'
                    : 'This project now reads the old events table. It can take a minute to apply.'
            )
        },
    })),
    afterMount(({ actions }) => {
        actions.loadEventsTable()
    }),
])
